#include "facts/generated/facts_data.hpp"

namespace nikos::facts::data {

const Fact kSpaceFacts[kFactsPerCategory] = {
    {"space-001", "Obrót dłuższy od roku", "Wenus obraca się wokół osi przez 243 dni ziemskie, a Słońce obiega w 225 dni. Jednak od wschodu do wschodu Słońca mija tam około 117 dni."},
    {"space-002", "Oddalający się Księżyc", "Księżyc oddala się od Ziemi średnio o 3,8 cm rocznie. To mniej więcej tyle, ile rosną paznokcie w ciągu roku."},
    {"space-003", "Saturn lżejszy od wody", "Średnia gęstość Saturna jest mniejsza od gęstości wody. Gdyby istniał odpowiednio wielki zbiornik, planeta mogłaby w teorii unosić się na wodzie."},
    {"space-004", "Niebieski zachód na Marsie", "Na Marsie niebo wokół zachodzącego Słońca bywa niebieskawe. To efekt rozpraszania światła przez drobny pył."},
    {"space-005", "Neptun odkryty obliczeniami", "Położenie Neptuna obliczono, zanim odnaleziono go na niebie. Wskazówką były niewyjaśnione zaburzenia ruchu Urana."},
    {"space-006", "Spóźnione światło Słońca", "Obraz Słońca dociera do nas z opóźnieniem. Jego światło potrzebuje około 8 minut i 20 sekund, by dotrzeć do Ziemi."},
    {"space-007", "Gejzery Enceladusa", "Z Enceladusa, księżyca Saturna, tryskają w kosmos lód i para. Pod jego lodową skorupą ukryty jest ocean."},
    {"space-008", "Kosmiczne latarnie", "Pulsary wysyłają regularne błyski niczym latarnie morskie. To wirujące gwiazdy neutronowe, których wiązki promieniowania omiatają kosmos."},
    {"space-009", "Ukryte planety", "Planetę można odkryć, nawet jeśli jej nie widać. Przechodząc przed gwiazdą, na chwilę przyciemnia jej światło."},
    {"space-010", "Podróż Voyagera 1", "Voyager 1 dotarł do przestrzeni międzygwiazdowej w 2012 roku. Minięcie zewnętrznych granic obłoku Oorta może mu zająć jeszcze około 30 tysięcy lat."},
    {"space-011", "Lód na Merkurym", "Na Merkurym, najbliższej Słońcu planecie, odkryto lód wodny. Przetrwał w kraterach, do których nigdy nie dociera światło Słońca."},
    {"space-012", "Długa zima Urana", "Na Uranie zima przy biegunie może trwać około 21 ziemskich lat. Planeta obraca się niemal na boku."},
    {"space-013", "Wirujący Jowisz", "Jowisz jest największą planetą i obraca się najszybciej. Pełny obrót zajmuje mu niecałe 10 godzin."},
    {"space-014", "Wulkan na Io", "Na Io, księżycu Jowisza, sfotografowano wybuch wulkanu. Pióropusz gazu i pyłu sięgał 400 km nad powierzchnię."},
    {"space-015", "Ganimedes większy od Merkurego", "Ganimedes, księżyc Jowisza, jest większy od Merkurego. To jedyny znany księżyc z własnym polem magnetycznym."},
    {"space-016", "Ocean pod lodem Europy", "Europa, księżyc Jowisza, prawdopodobnie skrywa ocean. Może mieć dwa razy więcej wody niż wszystkie ziemskie oceany."},
    {"space-017", "Metanowy deszcz na Tytanie", "Na Tytanie, księżycu Saturna, pada metanowy deszcz. Tamtejsze jeziora wypełniają ciekły metan i etan."},
    {"space-018", "Lodowe góry Plutona", "Na Plutonie wznoszą się góry z lodu wodnego. W tamtejszym mrozie taki lód jest twardy jak skała."},
    {"space-019", "Masa Słońca", "Słońce skupia około 99,8% masy całego Układu Słonecznego. Na wszystkie planety i pozostałe ciała przypada zaledwie 0,2%."},
    {"space-020", "16 wschodów na ISS", "Z pokładu ISS można zobaczyć 16 wschodów Słońca na dobę. Stacja okrąża Ziemię co około 90 minut."},
    {"space-021", "Dwa warkocze komety", "Warkocz jonowy komety jest odpychany od Słońca przez wiatr słoneczny. Warkocz pyłowy reaguje głównie na ciśnienie światła i może się zakrzywiać."},
    {"space-022", "Słońce i Księżyc na niebie", "Słońce jest około 400 razy szersze od Księżyca i średnio około 400 razy dalej. Dlatego ich tarcze mają zbliżone rozmiary kątowe."},
    {"space-023", "Czarna dziura jak soczewka", "Czarna dziura potrafi zniekształcić obraz odległej gwiazdy. Jej grawitacja ugina światło niczym ogromna soczewka."},
    {"space-024", "Tlen z Marsa", "Na Marsie urządzenie MOXIE wytworzyło tlen z atmosfery. Rozdzielało dwutlenek węgla na tlen i tlenek węgla."},
    {"space-025", "Łączność za Księżycem", "Z dalekiej strony Księżyca nie ma bezpośredniej łączności z Ziemią. Sygnał zasłania sam Księżyc, więc potrzebny jest przekaźnik."},
    {"space-026", "Kolory gwiazd", "Niebieskie gwiazdy są gorętsze od czerwonych. Pierwsze mogą mieć ponad 30 000 K, drugie około 3000 K."},
    {"space-027", "Biały karzeł", "Biały karzeł może mieć rozmiary Ziemi. W tak małym obiekcie mieści się nawet połowa masy Słońca."},
    {"space-028", "Gorąca korona Słońca", "Zewnętrzna atmosfera Słońca jest gorętsza od jego powierzchni. Osiąga miliony stopni, choć powierzchnia ma około 5500°C."},
    {"space-029", "Gwiazdy żyjące biliony lat", "Niektóre gwiazdy mogą żyć dłużej, niż istnieje Wszechświat. Małym czerwonym karłom paliwo może wystarczyć na biliony lat."},
    {"space-030", "Złoto z gwiazd neutronowych", "Złoto może powstawać przy zderzeniu gwiazd neutronowych. W takim kataklizmie tworzą się też platyna i inne ciężkie pierwiastki."},
    {"space-031", "Andromeda gołym okiem", "Przy ciemnym niebie galaktykę Andromedy widać bez teleskopu. Jej światło dociera do nas po około 2,5 miliona lat."},
    {"space-032", "Najstarsze światło", "Istnieje światło starsze niż wszystkie gwiazdy. Wyemitowano je około 380 000 lat po Wielkim Wybuchu."},
    {"space-033", "Niewidzialne 95% Wszechświata", "Zwykła materia to tylko około 5% zawartości Wszechświata. Reszta przypada na ciemną materię i ciemną energię."},
    {"space-034", "Tysiące galaktyk Hubble’a", "Na jednym obrazie Hubble'a widać około 5500 galaktyk. To maleńki fragment nieba, mniejszy niż tarcza Księżyca."},
    {"space-035", "Samotne planety", "Nie wszystkie planety krążą wokół gwiazd. Część samotnych planet mogła zostać wyrzucona z dawnych układów."},
    {"space-036", "Cisza w kosmosie", "W kosmicznej próżni nie słychać nawet wybuchu. Dźwięk potrzebuje materii, by się rozchodzić."},
    {"space-037", "Zegary GPS i Einstein", "Zegary satelitów GPS wyprzedzają ziemskie o 38 mikrosekund na dobę. Nawigacja musi uwzględniać teorię względności Einsteina."},
    {"space-038", "Fale grawitacyjne", "W 2015 roku po raz pierwszy wykryto fale grawitacyjne. Powstały podczas zderzenia dwóch czarnych dziur."},
    {"space-039", "Mars pozornie zawraca", "Mars potrafi na nocnym niebie pozornie zawrócić. To złudzenie, gdy szybsza Ziemia wyprzedza go na orbicie."},
    {"space-040", "Spadające gwiazdy", "Spadająca gwiazda może być wielkości ziarnka piasku. To drobina, której przelot rozświetla atmosferę."},
    {"space-041", "Hel odkryty na Słońcu", "Hel odkryto na Słońcu, zanim znaleziono go na Ziemi. Zdradziła go nieznana żółta linia w widmie światła."},
    {"space-042", "Pierwszy obraz czarnej dziury", "Pierwszy obraz cienia czarnej dziury pokazano w 2019 roku. Jasny pierścień tworzy gorący gaz wokół niej."},
    {"space-043", "Czerwone światło galaktyk", "Światło odległych galaktyk jest rozciągnięte ku czerwieni. To ślad rozszerzania się samej przestrzeni."},
    {"space-044", "Gwiazda Polarna", "Gwiazda Polarna nie jest najjaśniejszą gwiazdą nieba. Pokazuje północ, bo leży blisko kierunku ziemskiej osi obrotu."},
    {"space-045", "Radioteleskopy", "Radioteleskopy mogą badać kosmos nawet za dnia. Dłuższe fale radiowe przechodzą także przez chmury."},
    {"space-046", "Lustro teleskopu Webba", "Lustro teleskopu Webba ma 18 sześciokątnych części. Złożono je do startu, bo całe lustro nie mieściło się w rakiecie."},
    {"space-047", "Sonda Parker", "Sonda Parker przeleciała przez zewnętrzną atmosferę Słońca. Przed żarem chroni ją specjalna osłona."},
    {"space-048", "Dlaczego astronauci się unoszą", "Astronauci na stacji kosmicznej unoszą się mimo grawitacji. Stacja i wszystko w niej nieustannie spadają wokół Ziemi."},
    {"space-049", "Zdjęcia z powierzchni Wenus", "Wenera 13 pracowała na powierzchni Wenus tylko 127 minut. Zdążyła przesłać pierwsze kolorowe zdjęcia jej krajobrazu."},
    {"space-050", "Próbki asteroidy Bennu", "Sonda OSIRIS-REx przywiozła na Ziemię próbki asteroidy Bennu. W ich minerałach znaleziono ślady dawnego kontaktu z wodą."},
    {"space-051", "Planety wokół pulsarów", "Pierwsze potwierdzone egzoplanety odkryto przy pulsarze. Krążą wokół pozostałości po martwej gwieździe."},
    {"space-052", "Gorące jowisze", "Niektóre gazowe olbrzymy okrążają swoje gwiazdy w kilka dni. Nazywa się je gorącymi jowiszami."},
    {"space-053", "Planety z dwoma słońcami", "Istnieją planety okrążające dwie gwiazdy naraz. Ich niebo może mieć dwa słońca."},
    {"space-054", "Blokada pływowa", "Księżyc stale pokazuje Ziemi niemal tę samą półkulę. To skutek synchronizacji obrotu z obiegiem."},
    {"space-055", "Odwrotna rotacja Wenus", "Wenus obraca się w kierunku przeciwnym do większości planet. Dlatego Słońce pozornie wschodzi tam na zachodzie."},
    {"space-056", "Sześciokąt na Saturnie", "Nad północnym biegunem Saturna wiruje strumień gazu w kształcie sześciokąta. Jego średnica przekracza dwukrotność średnicy Ziemi."},
    {"space-057", "Pierścienie nie tylko Saturna", "Pierścienie mają również Jowisz, Uran i Neptun. Są jednak znacznie słabiej widoczne niż pierścienie Saturna."},
    {"space-058", "Krótki rok Merkurego", "Merkury obiega Słońce w około 88 ziemskich dni. To najkrótszy rok w Układzie Słonecznym."},
    {"space-059", "Deszcz diamentów?", "W głębi Urana i Neptuna mogą powstawać kryształy diamentu. To hipoteza oparta na modelach i eksperymentach."},
    {"space-060", "Księżyc z oceanem magmy", "Młody Księżyc prawdopodobnie miał ocean stopionych skał. Świadczy o tym skład jego dawnej skorupy."},
    {"space-061", "Żagiel napędzany światłem", "Światło Słońca wywiera niewielki nacisk na powierzchnie. Żagiel kosmiczny może dzięki niemu zmieniać ruch sondy bez zużywania paliwa."},
    {"space-062", "Pomiędzy planetą a gwiazdą", "Brązowe karły są zbyt mało masywne, by trwale podtrzymywać syntezę wodoru jak gwiazdy. Nie są jednak zwykłymi planetami."},
    {"space-063", "Gwiazdy podwójne", "Wiele gwiazd należy do układów wielokrotnych. Dwie gwiazdy mogą krążyć wokół wspólnego środka masy."},
    {"space-064", "Niebo w podczerwieni", "Pył kosmiczny przesłania część światła widzialnego. Obserwacje w podczerwieni pozwalają zajrzeć do obłoków pyłu."},
    {"space-065", "Gwiazdy i pierwiastki", "W gwiazdach powstają liczne pierwiastki cięższe od helu. Część trafia do przestrzeni po śmierci gwiazd."},
    {"space-066", "Mgławica planetarna", "Mgławica planetarna nie musi mieć nic wspólnego z planetami. Tworzy ją materia odrzucona przez starzejącą się gwiazdę."},
    {"space-067", "Słońce nie jest w centrum", "Słońce krąży wokół centrum Drogi Mlecznej. Pełen obieg trwa około 230 milionów lat."},
    {"space-068", "Spłaszczone gwiazdy", "Bardzo szybki obrót może spłaszczać gwiazdę na biegunach. Wtedy jej równik jest wyraźnie szerszy."},
    {"space-069", "Gromady kuliste", "Gromady kuliste skupiają nawet setki tysięcy starych gwiazd. Krążą wokół wielu galaktyk."},
    {"space-070", "Planeta na skraju", "Neptun został odwiedzony z bliska tylko przez jedną sondę. Był nią Voyager 2 w 1989 roku."},
    {"space-071", "Ciemne niebo Księżyca", "Na Księżycu nie ma gęstej atmosfery rozpraszającej błękitne światło. Niebo wygląda czarno nawet za dnia."},
    {"space-072", "Szybkie rozbłyski radiowe", "Szybkie błyski radiowe trwają ułamki sekund. Część z nich powiązano z magnetarami."},
    {"space-073", "Największa góra Marsa", "Olympus Mons to olbrzymi wulkan tarczowy na Marsie. Jego wysokość wynosi około 22 km, zależnie od poziomu odniesienia."},
    {"space-074", "Planeta zdradza swoją masę", "Niewidoczną planetę można wykryć po drobnych zmianach prędkości jej gwiazdy. Gwiazda i planeta krążą wokół wspólnego środka masy."},
    {"space-075", "Neutrina w antarktycznym lodzie", "Detektor IceCube wykrywa ślady neutrin w lodzie Antarktydy. Niektóre z tych cząstek przybywają spoza Układu Słonecznego."},
    {"space-076", "Pustka nie jest pusta", "Nawet próżnia kosmiczna zawiera cząstki i promieniowanie. Przestrzeń między galaktykami nie jest idealnie pusta."},
    {"space-077", "Dlaczego planety są kuliste", "Grawitacja dużych ciał przyciąga materię ku środkowi. Dlatego duże planety przyjmują kształt bliski kuli."},
    {"space-078", "Skąd bierze się zaćmienie", "Zaćmienie Słońca zachodzi, gdy Księżyc zasłania jego tarczę. Nie zdarza się przy każdym nowiu z powodu nachylenia orbity."},
    {"space-079", "Wodór we Wszechświecie", "Wodór jest najpowszechniejszym pierwiastkiem we Wszechświecie. Powstał w ogromnej ilości krótko po Wielkim Wybuchu."},
    {"space-080", "Dwie różne strony Księżyca", "Skorupa po niewidocznej z Ziemi stronie Księżyca jest średnio grubsza. Pomogła to wykazać misja GRAIL."},
    {"space-081", "Księżyc się trzęsie", "Na Księżycu występują trzęsienia zwane moonquakes. Niektóre są związane z pływami wywoływanymi przez Ziemię."},
    {"space-082", "Dzień na Plutonie", "Pluton obraca się wokół osi przez około 6,4 ziemskiego dnia. Jego największy księżyc Charon ma podobny okres obiegu."},
    {"space-083", "Ogrody na orbicie", "Na ISS uprawiano między innymi sałatę i rzodkiewki. Badania roślin pomagają planować długie loty kosmiczne."},
    {"space-084", "Najjaśniejsza planeta", "Wenus zwykle świeci na naszym niebie jaśniej niż inne planety. Pomagają w tym jej chmury odbijające światło Słońca."},
    {"space-085", "Mars ma dwa księżyce", "Marsowi towarzyszą Fobos i Deimos. Oba są małe i mają nieregularne kształty."},
    {"space-086", "Słońce też wiruje", "Słońce nie obraca się jak sztywna kula. Jego równik wiruje szybciej niż okolice biegunów."},
    {"space-087", "Ciemne plamy Słońca", "Plamy słoneczne są chłodniejsze od otoczenia. Wciąż jednak są bardzo gorące i wiążą się z silnymi polami magnetycznymi."},
    {"space-088", "Japet — księżyc o dwóch barwach", "Japet, księżyc Saturna, ma jedną półkulę bardzo ciemną, a drugą znacznie jaśniejszą. Różnicę potwierdziły obserwacje sond."},
    {"space-089", "Kosmiczna sieć", "Galaktyki tworzą ogromne włókna i gromady. Pomiędzy nimi znajdują się rozległe obszary o małej gęstości materii."},
    {"space-090", "Droga Mleczna ma halo", "Naszą galaktykę otacza rozległe halo gwiazd i ciemnej materii. Wykracza ono daleko poza jasny dysk galaktyczny."},
    {"space-091", "Triton krąży pod prąd", "Triton, największy księżyc Neptuna, krąży przeciwnie do obrotu planety. To wskazówka, że mógł zostać przechwycony przez jej grawitację."},
    {"space-092", "Granica Układu Słonecznego", "Wpływ wiatru słonecznego tworzy wokół Słońca ogromny obszar zwany heliosferą. Jej rozmiary zmieniają się pod wpływem otoczenia."},
    {"space-093", "Gwiazdy o dwóch twarzach", "Układ zaćmieniowy to dwie gwiazdy zasłaniające się wzajemnie. Ich zmiany jasności zdradzają rozmiary i orbity."},
    {"space-094", "Chemia między gwiazdami", "W przestrzeni międzygwiazdowej wykryto liczne cząsteczki. Wśród nich są związki organiczne obecne w zimnych obłokach."},
    {"space-095", "Merkury z ogonem", "Merkury ma rozległy, bardzo słaby ogon sodowy przypominający kometarny. Tworzą go atomy uwalniane z powierzchni planety."},
    {"space-096", "Gwiazdy wyrzucone z domu", "Niektóre gwiazdy pędzą przez kosmos po wyrzuceniu z macierzystej gromady. Mogą je rozpędzać grawitacyjne spotkania innych gwiazd."},
    {"space-097", "Dlaczego Mars jest czerwony", "Czerwony odcień Marsa pochodzi głównie od związków żelaza. Pył pokrywający planetę zawiera utlenione minerały."},
    {"space-098", "Zorze na innych planetach", "Zorze obserwuje się nie tylko na Ziemi. Występują też między innymi na Jowiszu i Saturnie."},
    {"space-099", "Prędkość ucieczki z Ziemi", "Przy powierzchni Ziemi prędkość ucieczki wynosi około 11,2 km/s. Dotyczy to idealnego ruchu bez dalszego napędu i oporu powietrza."},
    {"space-100", "Podróż gwiazd", "Gwiazdy zmieniają położenie na niebie także względem siebie. Ten powolny ruch własny mierzą obserwatoria takie jak Gaia."},
};

}  // namespace nikos::facts::data
